#!/usr/bin/env tsx
/**
 * Generates the configuration reference documentation and `.env.example`
 * from the environment schema metadata in `src/config/env.ts`.
 *
 * Usage:
 *   npm run docs:config          # write generated files
 *   npm run docs:config -- --check  # verify committed files are up to date
 *
 * The generator is deterministic: given the same schema metadata it always
 * produces byte-identical output.
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import {
  envSchemaMetadata,
  type EnvVarMetadata,
} from '../src/config/env.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(__dirname, '..');

const DOCS_PATH = resolve(repoRoot, 'docs/configuration.md');
const ENV_EXAMPLE_PATH = resolve(repoRoot, '.env.example');

const GENERATED_START = '<!-- BEGIN GENERATED CONFIG TABLE -->';
const GENERATED_END = '<!-- END GENERATED CONFIG TABLE -->';

const ENV_EXAMPLE_HEADER = `# This file is generated by \`npm run docs:config\`. Do not edit by hand.
# Regenerate with: npm run docs:config
`;

/**
 * Sort metadata entries by variable name so output is stable regardless of
 * object key ordering in the source schema.
 */
function sortedMetadata(): EnvVarMetadata[] {
  return [...envSchemaMetadata].sort((a, b) => a.name.localeCompare(b.name));
}

function escapeTableCell(value: string): string {
  return value.replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
}

function formatDefault(meta: EnvVarMetadata): string {
  if (meta.default === undefined) {
    return '—';
  }
  if (typeof meta.default === 'string') {
    return meta.default === '' ? '`""`' : `\`${meta.default}\``;
  }
  return `\`${String(meta.default)}\``;
}

function formatExample(meta: EnvVarMetadata): string {
  if (meta.example === undefined) {
    return '—';
  }
  return `\`${meta.example}\``;
}

function formatRequired(meta: EnvVarMetadata): string {
  return meta.required ? 'Yes' : 'No';
}

function formatSecret(meta: EnvVarMetadata): string {
  return meta.secret ? 'Yes' : 'No';
}

/**
 * Build the generated markdown table section.
 */
export function generateConfigTable(): string {
  const rows = sortedMetadata().map((meta) => {
    const cells = [
      `\`${meta.name}\``,
      escapeTableCell(meta.description),
      formatRequired(meta),
      formatDefault(meta),
      formatExample(meta),
      formatSecret(meta),
    ];
    return `| ${cells.join(' | ')} |`;
  });

  const header = [
    '| Variable | Description | Required | Default | Example | Secret |',
    '| --- | --- | --- | --- | --- | --- |',
  ];

  return [GENERATED_START, '', ...header, ...rows, '', GENERATED_END].join('\n');
}

/**
 * Merge the generated table into the existing docs file, replacing the
 * content between the generated markers. If the markers are missing, the
 * table is appended at the end of the file.
 */
export function generateDocsContent(existing: string): string {
  const table = generateConfigTable();
  const startIdx = existing.indexOf(GENERATED_START);
  const endIdx = existing.indexOf(GENERATED_END);

  if (startIdx !== -1 && endIdx !== -1 && endIdx > startIdx) {
    const before = existing.slice(0, startIdx);
    const after = existing.slice(endIdx + GENERATED_END.length);
    return `${before}${table}${after}`;
  }

  const trimmed = existing.replace(/\s*$/, '');
  const separator = trimmed.length > 0 ? '\n\n' : '';
  return `${trimmed}${separator}${table}\n`;
}

/**
 * Build the `.env.example` file content.
 */
export function generateEnvExample(): string {
  const lines: string[] = [ENV_EXAMPLE_HEADER];

  for (const meta of sortedMetadata()) {
    if (meta.description) {
      lines.push(`# ${meta.description}`);
    }
    if (meta.required) {
      lines.push('# Required');
    }
    if (meta.secret) {
      lines.push('# Secret: do not commit real values');
    }
    if (meta.example !== undefined) {
      lines.push(`# Example: ${meta.example}`);
    }
    const value = meta.example ?? (meta.default !== undefined ? String(meta.default) : '');
    lines.push(`${meta.name}=${value}`);
    lines.push('');
  }

  // Normalise to a single trailing newline.
  return `${lines.join('\n').replace(/\n+$/, '')}\n`;
}

interface GeneratedFile {
  path: string;
  content: string;
}

function buildGeneratedFiles(): GeneratedFile[] {
  const existingDocs = existsSync(DOCS_PATH)
    ? readFileSync(DOCS_PATH, 'utf8')
    : '# Configuration\n';

  return [
    { path: DOCS_PATH, content: generateDocsContent(existingDocs) },
    { path: ENV_EXAMPLE_PATH, content: generateEnvExample() },
  ];
}

function main(): void {
  const check = process.argv.includes('--check');
  const files = buildGeneratedFiles();

  if (check) {
    const stale: string[] = [];
    for (const file of files) {
      const current = existsSync(file.path) ? readFileSync(file.path, 'utf8') : null;
      if (current !== file.content) {
        stale.push(file.path);
      }
    }
    if (stale.length > 0) {
      console.error('Generated configuration files are out of date:');
      for (const path of stale) {
        console.error(`  - ${path}`);
      }
      console.error('\nRun `npm run docs:config` and commit the result.');
      process.exit(1);
    }
    console.log('Generated configuration files are up to date.');
    return;
  }

  for (const file of files) {
    writeFileSync(file.path, file.content, 'utf8');
    console.log(`Wrote ${file.path}`);
  }
}

// Only run when invoked directly, so the module can be imported in tests.
const invokedDirectly =
  process.argv[1] !== undefined &&
  resolve(process.argv[1]) === fileURLToPath(import.meta.url);

if (invokedDirectly) {
  main();
}